# # 1. Source URL validity
# Reject malformed URLs and non-HTTP(S) schemes.
# 2. Source provenance
# Keep sources collected from actual web-search citation annotations distinct from URLs generated by the model.
# 3. Report reference integrity
# Ensure every source ID used in a report section or recommendation exists in the source catalogue.
# 4. Claim support
# A valid URL or source ID alone does not prove that a source supports the associated claim. We'll treat this as a separate, more advanced validation step.
# Step 4.2 — Integrate URL validation into researcher.py
#           Validation layer	                           Status
# URL syntax and HTTP(S) scheme	                        Implemented
# Duplicate URL detection	                            Implemented
# Report source-ID integrity	                        Implemented
# Source authenticity and current availability	        Not checked
# Whether a source genuinely supports a specific claim	Not yet implemented

import logging
from urllib.parse import urlsplit

logger = logging.getLogger(__name__)


def is_valid_http_url(url: str) -> bool:
    """Check URL syntax and require an HTTP(S) scheme and hostname."""
    if not isinstance(url, str) or not url.strip():
        return False

    try:
        parsed = urlsplit(url.strip())

        return (
            parsed.scheme.lower() in {"http", "https"}
            and bool(parsed.hostname)
            and parsed.username is None
            and parsed.password is None
        )
    except (ValueError, TypeError):
        return False


def validate_source_urls(sources: list) -> tuple[list, list[dict]]:
    """
    Keep sources with valid HTTP(S) URLs.
    Return (valid_sources, issues).
    """
    valid_sources = []
    issues = []
    seen_urls = set()

    for source in sources:
        url = getattr(source, "url", None)

        if not is_valid_http_url(url):
            issues.append({
                "type": "invalid_source_url",
                "url": str(url),
                "title": getattr(source, "title", ""),
            })
            continue

        normalized_url = url.strip()

        if normalized_url in seen_urls:
            issues.append({
                "type": "duplicate_source_url",
                "url": normalized_url,
                "title": getattr(source, "title", ""),
            })
            continue

        seen_urls.add(normalized_url)
        valid_sources.append(source)

    if issues:
        logger.warning(
            "Source URL validation found issues",
            extra={
                "component": "citation_validator",
                "issue_count": len(issues),
                "issues": issues,
            },
        )

    return valid_sources, issues


def validate_report_source_ids(
    report,
    source_catalogue: dict,
) -> list[dict]:
    """
    Check that all source IDs referenced by the report exist.
    Supports the FinalReport sections and recommendations schema.
    """
    issues = []
    referenced_ids = []

    for section in getattr(report, "sections", []):
        referenced_ids.extend(
            getattr(section, "source_ids", []) or []
        )

    for recommendation in getattr(report, "recommendations", []):
        referenced_ids.extend(
            getattr(recommendation, "source_ids", []) or []
        )

    for source_id in referenced_ids:
        if source_id not in source_catalogue:
            issues.append({
                "type": "unknown_source_id",
                "source_id": source_id,
            })

    if issues:
        logger.warning(
            "Report source ID validation found issues",
            extra={
                "component": "citation_validator",
                "issue_count": len(issues),
                "issues": issues,
            },
        )
    else:
        logger.info(
            "Report source ID validation passed",
            extra={
                "component": "citation_validator",
                "reference_count": len(referenced_ids),
            },
        )

    return issues
